/** Bounded native sphere-pair check; character and chat stay available. */
final class HalfSwordContactPanel extends LinearLayout {
 final Button step,reset;final TextView label;final View drawing;final Paint paint=new Paint(3);ByteBuffer a,b,descriptor,point;boolean busy;int steps,revision;float moved;String testId;int testStage;boolean firstResolved,secondCulled;
 HalfSwordContactPanel(Context c){super(c);setOrientation(VERTICAL);setTag("half-sword-contact-panel");LinearLayout row=new LinearLayout(c);step=new Button(c);step.setText("Contact step");step.setTextSize(11);reset=new Button(c);reset.setText("Reset contacts");reset.setTextSize(11);row.addView(step,new LinearLayout.LayoutParams(0,-2,1));row.addView(reset,new LinearLayout.LayoutParams(0,-2,1));label=new TextView(c);label.setTextSize(11);label.setTextColor(0xffb9d1c4);row.addView(label,new LinearLayout.LayoutParams(0,-2,1));addView(row);drawing=new View(c){protected void onDraw(Canvas canvas){super.onDraw(canvas);float scale=Math.min(getWidth()/5f,getHeight()/2.3f),cx=getWidth()*.43f,cy=getHeight()*.5f;paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(2);paint.setColor(0xff88dbb3);canvas.drawCircle(cx+moved*scale,cy,scale,paint);paint.setColor(0xffd4ad79);canvas.drawCircle(cx+1.5f*scale,cy,scale,paint);}};drawing.setContentDescription("Isolated sphere pair contact check; character unchanged");row.addView(drawing,new LinearLayout.LayoutParams((int)(80*c.getResources().getDisplayMetrics().density),-1));resetState();step.setOnClickListener(new View.OnClickListener(){public void onClick(View v){requestStep();}});reset.setOnClickListener(new View.OnClickListener(){public void onClick(View v){if(!busy)resetState();}});}
 static ByteBuffer buffer(int size){return ByteBuffer.allocateDirect(size).order(ByteOrder.nativeOrder());}
 static void transform(ByteBuffer d,int offset,double x){d.putDouble(offset+24,1.);d.putDouble(offset+32,x);for(int k=0;k<3;k++)d.putDouble(offset+64+8*k,1.);}
 void resetState(){revision++;steps=0;moved=0;a=buffer(352);b=buffer(352);descriptor=buffer(496);point=buffer(72);for(int side=0;side<2;side++){ByteBuffer body=side==0?a:b;double x=side==0?0.:1.5;body.putDouble(0x80+24,1.);body.putDouble(0xc0+24,1.);body.putDouble(0xe0,x);body.putDouble(0x110,x);body.putFloat(0x134,side==0?1f:0f);for(int k=0;k<3;k++)body.putFloat(0x40+20*k,side==0?1f:0f);transform(descriptor,96*side,x);transform(descriptor,192+96*side,x);descriptor.putDouble(384+32*side,1.);for(int k=0;k<3;k++)descriptor.putFloat(448+12*side+4*k,1f);}descriptor.putFloat(480,1f);descriptor.putFloat(484,1f);descriptor.putFloat(488,.5f);label.setText("Sphere check · ready");step.setEnabled(true);reset.setEnabled(true);drawing.invalidate();}
 boolean requestStep(){if(busy||steps>=2){label.setText(busy?"Contact pending":"Two-step limit · reset");return false;}busy=true;step.setEnabled(false);reset.setEnabled(false);label.setText("Resolving contact…");final int token=revision;final ByteBuffer aa=a,bb=b,dd=descriptor,pp=point;new Thread(new Runnable(){public void run(){int result=-999;String error="";try{HalfSwordBridge.load(getContext());result=HalfSwordBridge.sphereBodyContactStep(aa,bb,dd,pp);}catch(Exception e){error=e.toString();}catch(LinkageError e){error=e.toString();}final int code=result;final String failure=error;post(new Runnable(){public void run(){if(token!=revision)return;busy=false;steps++;moved=aa.getFloat(0);label.setText(failure.length()>0?"Contact unavailable":code==0?"Overlap resolved · "+steps+"/2":code==1?"Separated · "+steps+"/2":"Contact rejected "+code);step.setEnabled(steps<2&&failure.length()==0);reset.setEnabled(true);drawing.invalidate();if(testId!=null)advanceCheck(code,failure);}});}},"HalfSwordContact").start();return true;}
 protected void onAttachedToWindow(){super.onAttachedToWindow();final File request=new File(getContext().getFilesDir(),"home/.trough/half-sword-contact-check-request.json");if(request.isFile())post(new Runnable(){public void run(){try{JSONObject json=new JSONObject(new String(Payloads.readSmall(request),"UTF-8"));testId=json.getString("id");request.delete();testStage=0;resetState();requestStep();}catch(Exception ignored){}}});}
 protected void onDetachedFromWindow(){busy=false;resetState();super.onDetachedFromWindow();}
 void advanceCheck(int code,String error){try{if(testStage==0){firstResolved=code==0&&error.length()==0&&Math.abs(moved+.5f)<1e-6&&b.getFloat(0)==0f;testStage=1;requestStep();return;}secondCulled=code==1&&Math.abs(moved+.5f)<1e-6;boolean capped=!requestStep();String id=testId;testId=null;resetState();JSONObject receipt=new JSONObject();receipt.put("id",id);receipt.put("passed",firstResolved&&secondCulled&&capped&&steps==0&&moved==0);receipt.put("native_first_resolved",firstResolved);receipt.put("native_second_culled",secondCulled);receipt.put("third_step_capped",capped);receipt.put("reset_restored",steps==0&&moved==0);receipt.put("attached",getWindowToken()!=null);receipt.put("media_paused",new File(getContext().getFilesDir(),"home/.trough/media/playback-paused").exists());File out=new File(getContext().getFilesDir(),"home/.trough/half-sword-contact-check-result.json");try(FileOutputStream stream=new FileOutputStream(out)){stream.write(receipt.toString().getBytes("UTF-8"));stream.getFD().sync();}}catch(Exception ignored){}}
}
